-- =========================================================================
-- Core Programme track seed
--
-- GENERATED FILE - do not edit by hand.
-- Source: lib/programme/track-spec.ts   Regenerate: npm run seed:programme
--
-- Idempotent: every insert is guarded, so running this twice is a no-op.
-- Run AFTER migrations. Safe to run against an existing track.
--
-- Learn videos are REFERENCED, never copied: learn_video_id is resolved by
-- exact title match against learn_videos and left null when there's no
-- match, to be bound later in the admin Track-items screen.
-- =========================================================================

insert into public.programme_tracks (name, slug, is_active)
select 'Core Programme', 'core-programme', true
 where not exists (select 1 from public.programme_tracks where slug = 'core-programme');

-- 41 items: day 0 gate, 15 x (video + use_example), 3 sessions,
-- 3 quizzes (end of each week), 3 submission slots, 1 post check-in.
with track as (
  select id from public.programme_tracks where slug = 'core-programme'
), spec(type, title, description, day_index, sort_order, learn_video_title, config_json) as (
  values
    ('questionnaire_baseline', 'Your AI Score - 3-minute check-in', 'A quick self-assessment. It sets your starting point and unlocks the programme.', 0, 0, null, '{}'::jsonb),
    ('video', 'What is AI and how does it work?', 'Prediction rather than lookup, the context window, training cutoff vs live data, the three failure sources and Time-Back Log setup.', 1, 0, 'What is AI and how does it work?', '{}'::jsonb),
    ('use_example', 'Task', 'Sign in to Claude with your Phlo email, install the desktop app, then run one real task from this week through it.
Submit the link to that task.', 1, 1, null, '{}'::jsonb),
    ('submission_slot', 'Work sample (before)', null, 1, 4, null, '{"kind":"work_sample_pre","visibility":"private"}'::jsonb),
    ('video', 'When to use AI and when not to', null, 2, 0, 'When to use AI and when not to', '{}'::jsonb),
    ('use_example', 'Task', 'Pick three jobs from this week:
- one you are confident Claude will do well
- one you are confident Claude will not do well
- one where you are not sure
Before you open Claude, write down how you think each will go and rate yourself Certain, Fairly confident or Guessing. Then run all three, including the one you expect to fail.
Compare what you got with what you expected. Anything that worked when you thought it would not is a job to hand over from now on. Anything that came back wrong is one to keep checking.
Submit the link to one of these, ideally the one that surprised you most.', 2, 1, null, '{}'::jsonb),
    ('video', 'Prompting', null, 3, 0, 'Prompting', '{}'::jsonb),
    ('use_example', 'Task', 'Take a Project you''ve already built (or build a new one) and use the CRISPE framework in the instructions.
Run a chat here again and check the output.
Submit the Project as an example of one using a framework.', 3, 1, null, '{}'::jsonb),
    ('session', 'Live session 1', null, 3, 2, null, '{"slots":2}'::jsonb),
    ('video', 'Projects', null, 4, 0, 'Projects', '{}'::jsonb),
    ('use_example', 'Task', 'Pick one task you repeat and build a Project for it, giving it:
- custom instructions
- 2-3 knowledge files
- access with anyone else who could use it
Test it and check the output. If it is not what you need, the instructions are missing something, so add it and run it again.
Submit the link to the Project below.', 4, 1, null, '{}'::jsonb),
    ('video', 'Connectors & MCP', null, 5, 0, 'Connectors & MCP', '{}'::jsonb),
    ('use_example', 'Task', 'Go to Customize > Connectors and enable the tools you use daily.
Click on a specific connector and check the permissions that it allows by default. If you need additional functionality or are unsure what functionality is safe to enable for a specific connector, let Haseeb know.
Disconnect anything you added to have a look at and are not going to use.', 5, 1, null, '{}'::jsonb),
    ('quiz', 'Week 1 Quiz', null, 5, 3, null, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":1,"question":"In an ordinary Chat, with web search turned off and no Connectors enabled, you ask Claude for the current list price of a product line. It answers with a precise figure, to the penny. Where did that number come from?","options":["It looked the price up and reported back what it found","It calculated it from related figures that it does hold","It predicted a plausible figure from patterns in its training data","It reported the last value it saw, so it is current unless the price moved","It inferred it from your earlier messages in this Chat"],"correct":2,"explanation":"Nothing was looked up. Claude predicts the next words, so a figure turns up in whatever shape the sentence needs, and the two decimal places are a writing habit, not evidence. When the number is right, that is the training data happening to agree with reality. Anything that changes over time needs a Connector, or a source you open yourself."},{"day":1,"question":"Two hours into a long Chat, Claude starts breaking a formatting rule you set at the very beginning and had been following all along. What is the likeliest cause?","options":["It has decided your later instructions override the earlier one","The Chat has outgrown what Claude can hold in view at once","Output quality degrades over a long session, so it needs restarting","Its training data disagrees with the rule that you set","The rule was not stated firmly enough for it to stick"],"correct":1,"explanation":"Everything Claude can see has to fit in one window, and a long chat pushes the start of it out of range. Say the rule again, or carry the essentials into a fresh chat. Saying it more firmly will not help. The instruction is not being ignored, it is no longer visible."},{"day":2,"question":"Which of these is the weakest candidate for handing to Claude?","options":["Drafting the first version of a recurring internal update","Summarising a supplier contract you will read properly afterwards","Signing off the final numbers in the month-end pack","Reformatting a messy stock export into a consistent structure","Drafting a tender rejection letter that is reviewed before it goes"],"correct":2,"explanation":"Drafting, summarising and reformatting are where Claude saves you time, and an awkward subject does not change that as long as you read the draft before it goes. Signing off is the one thing that cannot move, because you cannot hand over being accountable. Use Claude to prepare what the decision rests on, then make the decision yourself."},{"day":2,"question":"Two colleagues use Claude on similar work. One handed over a whole process end to end and is disappointed. The other handed over only the drafting and is not. What explains the gap?","options":["The second colleague simply writes better prompts than the first","Judgement and accountability do not transfer, but drafting does","The first colleague is working on genuinely more complex material","The second colleague has been using the tool for a lot longer","The first colleague needs a Project and the second already has one"],"correct":1,"explanation":"Complexity is not the dividing line, and neither is being good with the tool. What moves across is the blank page and the repetitive middle. What does not is deciding and owning the result, so handing over a whole process always disappoints at the point where somebody has to answer for it. Prompting and Projects both help, and neither changes that."},{"day":3,"question":"A prompt in a Chat returns content that is accurate and complete, but it reads like a different company wrote it. Which part of CRISPE is missing?","options":["Context","Instructions","Parameters","Role","Style"],"correct":4,"explanation":"Style is tone, register and voice. The content being right tells you Context and Instructions did their job. Role changes the expertise Claude writes from, not the voice it writes in, and Parameters set length, format and what to leave out. Correct but reads wrong means Style."},{"day":3,"question":"You have to write this month''s report in exactly the same shape as last month''s: the same sections, in the same order, with the same kind of summary at the top. Which part of CRISPE does most of the work?","options":["Instructions, listing out every formatting rule you can think of first","Example, pasting last month''s report so it can copy the shape","Parameters, specifying the length and the number of sections","Context, explaining who reads the report and what they need from it","Role, so it writes as the person who produced the original one"],"correct":1,"explanation":"One example says more than a page of rules, and it clears up the ambiguity a description always leaves behind. Parameters and Instructions can get the shape close and will never get the phrasing. Role and Context change how Claude thinks about the job, not what it hands you."},{"day":4,"question":"Every week you paste the same background into a new Chat before you can ask your real question: your team''s terminology, the format you need and the standing constraints. What fixes that properly?","options":["Keep the preamble in a note and paste it at the top of each Chat","Write one much longer prompt so that nothing important gets missed","Ask Claude to remember the background at the end of each Chat","Put the background and reference files in a Project","Add a Connector to the systems that background describes"],"correct":3,"explanation":"A Project holds the background, so every chat inside it starts briefed and nobody keeps a preamble up to date by hand. A pasted note goes out of date the moment the format changes, and a longer prompt just moves the repetition somewhere else. A Connector fetches live data, which is a different problem."},{"day":4,"question":"A Project you built answers the exact question you built it around very well, and anything slightly different badly. What does that tell you?","options":["The knowledge files you gave it are too small to generalise from","Projects are built for one job, so varied work belongs in a Chat","The instructions describe one task rather than how you work","You need a separate Project for each question you want to ask","Requests have to be phrased the way you phrased the original one"],"correct":2,"explanation":"A Project that only answers the question you built it around is a saved prompt with extra steps. The background is the method, the vocabulary and the constraints, and all of that carries across requests. Building one per question gives you more to maintain and the same problem again in a month."},{"day":5,"question":"Several times a day you copy the same figures out of the same system and paste them into a Chat. What is that a signal for?","options":["A Connector, so Claude can reach the system itself","A longer prompt that carries more of the background with it","A Project holding the most recent export of those figures","Nothing, copy and paste is perfectly fine at that volume","A Scheduled Task that pastes the figures in for you each morning"],"correct":0,"explanation":"Copying the same figures by hand several times a day is the clearest sign a Connector will pay for itself. A Project holds background that changes slowly, and an export dropped into one is out of date the moment you save it. A schedule automates the ferrying, so you get the same stale figures on a timer."},{"day":5,"question":"A colleague worries that connecting a system to Claude will expose data they are not allowed to see. Which of the following is correct?","options":["They are right, a Connector reads the system and bypasses its permissions","Connectors are limited to data that the system already publishes openly","It depends entirely on which Connector and which system it is","It is safe provided they enable only the permissions the job needs","A Connector works within the access they already have"],"correct":4,"explanation":"A Connector is a route, not a promotion. Your colleague sees what their own login already lets them see. Checking the permissions a Connector allows by default is still worth doing, and the day''s task asks for it, but that is not what keeps the answer safe. Worth being clear about in a regulated business, because the worry is common and it puts people off something useful."}]}'::jsonb),
    ('video', 'Skills', null, 6, 0, 'Skills', '{}'::jsonb),
    ('use_example', 'Task', 'Pick something you explain to Claude again and again: how a report should be laid out, how a summary should be structured, the checks a piece of work has to pass before you send it.
Go to Customize > Skills and build a Skill for it. Let the built-in skill-creator draft it from your description. Give it:
- a description saying when to use it
- one task only
- the method it should follow
Test it in a fresh chat: ask for the task without naming the Skill, and try a few different wordings.
If it does not fire, the description is too vague. Make it say plainly when the Skill should be used, then try again.
Submit the link to the chat where your Skill fired on its own.', 6, 1, null, '{}'::jsonb),
    ('video', 'Scheduled Tasks', null, 7, 0, 'Scheduled Tasks', '{}'::jsonb),
    ('use_example', 'Task', 'Go to Scheduled in the sidebar and use New task to set up one job you do on a rhythm, with a frequency and a time you will be away from your desk.
Click Run now once and choose always allow on the permission prompts you recognise, or a scheduled run stalls waiting for you.
Do not tie it to a folder on your computer: those only run when you are there. Use your Connectors and files saved to your Claude account.
Submit the link to its first completed run, or a screenshot of it if there is no link to share.', 7, 1, null, '{}'::jsonb),
    ('video', 'Artifacts', null, 8, 0, 'Artifacts', '{}'::jsonb),
    ('use_example', 'Task', 'Pick something you rebuild most weeks - a status update, a meeting-prep sheet, a checklist - and ask Claude to make it as an Artifact you can reuse.
Do not settle for the first draft. Ask for one change in plain English and watch it update. If Claude answers in the chat instead of opening a panel, check Settings > Capabilities for Code execution and file creation, and ask Haseeb if that setting is not yours to change.
Share it. On our Team plan anyone signed in with a Phlo account can open it, so use made-up numbers, keep logins and keys out of it, and ask Haseeb first if it needs to go outside Phlo.
Submit the link to your Artifact.', 8, 1, null, '{}'::jsonb),
    ('session', 'Live session 2', null, 8, 2, null, '{"slots":2}'::jsonb),
    ('video', 'Cowork', null, 9, 0, 'Cowork', '{}'::jsonb),
    ('use_example', 'Task', 'Pick a boring job you keep putting off (e.g. merging a few documents into one summary, checking two lists against each other, tidying up and renaming a group of files). Put the files Cowork needs into one folder - don''t add anything else.
Open Cowork in the desktop app, point it to that folder and tell it the whole task in one sentence. Then set it to "Skip all approvals" to allow it to do the work without asking for approvals.
Cowork works on your real files, so keep this folder small and make sure there''s nothing unrelated or confidential in it.
Submit the link to the final output.', 9, 1, null, '{}'::jsonb),
    ('video', 'Claude Design', null, 10, 0, 'Claude Design', '{}'::jsonb),
    ('use_example', 'Task', 'Describe one screen or document you wish already existed: a landing page, a settings screen, a pitch deck, a one-pager.
Open Claude Design at claude.ai/design, or from the sidebar in the desktop app. Build it there, then ask for one change in plain English instead of keeping the first version.
Export what you end up with. The Export button gives you PowerPoint, PDF or a standalone page.
It is a research preview, so treat what comes out as a draft. Keep confidential designs, patient-facing material and private code out of it.
Submit the link to the design, or to the file you exported.', 10, 1, null, '{}'::jsonb),
    ('quiz', 'Week 2 Quiz', null, 10, 3, null, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":6,"question":"You have a reliable method for a recurring task and two colleagues want to use it. What makes a Skill the right home for it, rather than a Project or a saved prompt?","options":["They turn it on once, then it fires by itself","It stores the documents the task needs alongside the method","It runs to a timetable, whether or not the job came up","It gives Claude access to the system that the task depends on","It keeps the method private to the colleagues you name on it"],"correct":0,"explanation":"A Skill packages how you do something so other people''s chats can reach it. A colleague switches it on once, and after that the description is what makes it fire without anyone naming it. Documents belong in a Project, a timetable is a Scheduled Task, and system access is a Connector. Picking the wrong one is what makes simple work feel like hard work."},{"day":6,"question":"You built a Skill and it never fires unless you name it explicitly in the Chat. What is almost always wrong?","options":["The instructions inside the Skill have grown too long to parse","It has to be shared with your team before it will trigger at all","The task is too narrow for a Skill to be the right container","Its description is too vague to match what people actually ask","Skills only fire automatically for the person who created them"],"correct":3,"explanation":"The description is the trigger. Use this when formatting a monthly performance report fires when it should. Helps with reports never fires at all. Sharing changes who can reach a Skill, not whether it triggers, and a narrow task is exactly what a Skill wants."},{"day":7,"question":"From Scheduled in the sidebar you set a task to run the stock summary at 07:00 each Monday. You reach your desk at 08:30 and your laptop was shut overnight. What happens?","options":["It waits until you open the laptop, so the result arrives late","It ran at 07:00 without your machine, and the result is waiting","It is skipped entirely and runs again the following Monday","It fails, and you get a notification telling you that it failed","It ran at 07:00 but could not reach your Connectors while you were away"],"correct":1,"explanation":"Scheduled runs happen on Anthropic''s servers, so they keep to their timetable with your computer asleep and the desktop app shut, and your connected tools go with them. Nothing is deferred, skipped or failed. The one thing that still needs your machine is a task reaching files or apps on it. That is why you build a schedule on your Connectors and on files saved to your Claude account, and not on a folder."},{"day":7,"question":"A Scheduled Task you set up three weeks ago still runs, but you now rewrite most of its output before you use it. What should you do?","options":["Leave it running, since it is still saving you time overall","Delete it and go back to doing the whole task by hand again","Run it more often so that its output stays closer to current","Keep it, and log the saving as the full time the task once took","Fold what you keep rewriting back in, or retire the task"],"correct":4,"explanation":"Heavy editing means the task and the real work have drifted apart, and what you keep rewriting is the specification. Running it more often just gives you more to correct. Logging the old full cost is how a time saving turns into a number nobody believes. The saving is what the job costs now against what it cost before."},{"day":8,"question":"You have asked Claude for a checklist your team will use every week. Why ask for it as an Artifact rather than as text in the Chat?","options":["Artifacts are generated faster than the same answer in a Chat","Claude is more accurate when it writes into an Artifact","You get something you can edit, version and share on its own","It uses fewer messages, so you get more out of your limits","Anyone you share it with can edit your copy of it directly"],"correct":2,"explanation":"An Artifact is the output as an object instead of chat scrollback. You refine it in place, every version is kept, and you can share the checklist with people who do not need the conversation behind it. Speed and accuracy are the same either way. Sharing lets other people open and use it, which is not the same as giving them edit rights on yours."},{"day":8,"question":"You have built a margin calculator as an Artifact in Claude and you are about to share the link so your team can use it. This quarter''s real supplier prices are typed into it. What has to happen first?","options":["Share it, then message the team asking them not to forward the link","Nothing, a shared Artifact is reachable only by the people you send it to","Swap the real prices for made-up ones before you share it","Leave the real prices in and write a confidentiality note at the top of the page","Share it with only the two colleagues who actually need it"],"correct":2,"explanation":"Sharing is the step that changes who can see something. On our plan a shared Artifact opens for anyone at Phlo with the link, not just the people you had in mind, and it carries the files attached to the conversation that built it. Plenty of those people have no business seeing supplier pricing, so live figures are the wrong thing to leave in. A confidentiality note changes nothing about who can open the page, asking colleagues not to forward a link is not a control, and you cannot narrow a share to two names. It is everyone at Phlo or nobody."},{"day":9,"question":"Which of these is the strongest candidate for Cowork rather than an ordinary Chat?","options":["A question you need a single short answer to before this afternoon","Drafting an email to a supplier about a late delivery","Deciding which of two suppliers your team should move to","Working through a live document with a colleague at the same time","Merging six monthly reports into one summary and filing them"],"correct":4,"explanation":"Cowork earns its keep on assembly across a lot of files on your own machine. The work is tedious instead of difficult, and it ends in files instead of an answer. A short question and a draft are ordinary chat, deciding is yours, and two people cannot work in one Cowork session, so anything live and shared belongs elsewhere."},{"day":9,"question":"You are handing a job to Cowork in the desktop app and you have skipped the permission prompts so it can work without stopping to ask. What is keeping it away from files it has no business opening?","options":["The folder you pointed it at, and whatever you chose to put in it","Claude''s judgement about which of your files the task actually needs","The one-sentence brief, which tells it what it is allowed to open","The desktop app, which reaches your Claude account rather than your disk","Nothing much, so read every file it touched once the run has finished"],"correct":0,"explanation":"Skipping the prompts is what makes the folder the control. There is no per-step approval left, so the only thing between Cowork and a file is whether you put that file in scope before the run started. Claude has no way of knowing which of your documents are commercially sensitive. A brief describes the goal, it does not grant access. The desktop app is the route to your disk, not a limit on it: on our plan the run happens on Anthropic''s servers and reaches your files through that app, for the folders you connected and no others. Reading afterwards is worth doing, but by then it has already opened whatever was there."},{"day":10,"question":"You need a pitch deck for Monday and you want to shape the layout before it goes out. Where does Claude Design earn its place over an ordinary Chat?","options":["It writes the words on each slide more accurately than a Chat does","It signs the deck off, so nobody else has to review what it made","It keeps the deck''s source documents attached for the next revision","You shape the layout on a canvas and export the result as a PPTX","It is the only surface at Phlo that can read a PowerPoint file"],"correct":3,"explanation":"You get a canvas and a real export. You adjust spacing, colour and layout yourself, or ask for changes in plain English, and the Export button gives you PowerPoint, PDF or a standalone page. A Chat can draft the words, but hands them back as text for you to reassemble. Keeping the source documents for next time is what a Project is for. Nothing here removes the human review, and a Chat reads a PowerPoint file perfectly well."},{"day":10,"question":"Which of the following is the poorest fit for Claude Design as it stands today?","options":["An internal one-pager explaining a process change to your team","A rough settings screen, made to get a conversation started","A patient-facing leaflet going out under Phlo''s brand","A slide for Monday''s team meeting that you will talk over","A layout you want to react to before committing real time to it"],"correct":2,"explanation":"Two things make it the wrong fit. It is a research preview, so what comes out is a draft, and patient-facing material has to meet a standard a draft is not aiming at. Confidential designs and private code stay out for the same reason. Internal drafts, rough screens and something to react to are exactly what it is for."}]}'::jsonb),
    ('video', 'Claude Design 2', null, 11, 0, 'Claude Design 2', '{}'::jsonb),
    ('use_example', 'Task', 'Pick something you keep describing in words and hoping everyone pictures the same way: a screen you want built, a landing page, a one-pager.
Ask Claude Design to build it as something you can click through, not a picture of it. Attach the spec, brief or notes you already have, or you will get a screen that could belong to any company.
Ask for three versions, then take the best parts of each.
Export it as a PNG or a page, share it for comments, or hand it to Claude Code to build.
Submit the link to the prototype, or to what you exported.', 11, 1, null, '{}'::jsonb),
    ('video', 'Word & PowerPoint extensions', null, 12, 0, 'Word & PowerPoint extensions', '{}'::jsonb),
    ('use_example', 'Task', 'Install the Claude extensions for Word and PowerPoint from Microsoft AppSource. Office calls them add-ins, so look under Home > Add-ins on Windows or Tools > Add-ins on a Mac.
In each one''s settings, turn on ''Let Claude work across files'', and decide whether it should ask before each edit or just make them. On our Team plan that first setting is off until someone turns it on, so ask Haseeb if it is not yours to change.
In PowerPoint, open a deck you already have, select a few slides and ask for a specific change to those. It is better at tidying up what is there than at building a deck from nothing.
In Word, open a document with comments on it and ask Claude to summarise them and point out where they disagree. Turn track changes on first, so you can see every edit it makes.
Submit the link to the deck or the document you worked on.', 12, 1, null, '{}'::jsonb),
    ('video', 'Excel extension', null, 13, 0, 'Excel extension', '{}'::jsonb),
    ('use_example', 'Task', 'Install the Claude extension for Excel from Microsoft AppSource, the same way as yesterday, and open a workbook you actually use.
Tell it how the sheet is built before you ask for anything: which cells are inputs, which are worked out by formulas, what the currency is, and whether a number can go negative. Left to guess, it guesses.
Then give it a real job. Clean up a messy import, fix a formula that broke, or reconcile two sheets that disagree and explain the gap.
Check what it did before you use the numbers. It can be wrong and sound certain, so reconcile the sections that matter and read the assumptions it made.
Submit the link to the workbook.', 13, 1, null, '{}'::jsonb),
    ('session', 'Live session 3', null, 13, 2, null, '{"slots":2}'::jsonb),
    ('submission_slot', 'Capstone', null, 13, 4, null, '{"kind":"capstone","visibility":"cohort"}'::jsonb),
    ('video', 'Outlook extension', null, 14, 0, 'Outlook extension', '{}'::jsonb),
    ('use_example', 'Task', 'Install the Claude extension for Outlook. It is a public beta, and it opens from the ribbon when you have an email open.
Ask it to go through the inbox you dread on a Monday and sort it: what needs you, what it can draft for you, and what is noise.
Take one of its drafts, read it properly, then send it.
Submit a screenshot of what it sorted, since an Outlook email has no link you can share, or a link if something you made has one.', 14, 1, null, '{}'::jsonb),
    ('video', 'Wrap-up and next steps', 'A look back over the fifteen days and the one thing that happens next: pick a workflow you own, map it and put it up to be changed.', 15, 0, 'Wrap-up and next steps', '{}'::jsonb),
    ('use_example', 'Task', 'Go to Workflows and use Add new workflow to map a job you own that runs every week and quietly eats your time. Give it the real numbers: how often it runs, the hours a week it takes, what it costs and every step from start to finish.
Go to Suggestions, use Suggest something and link it to the workflow you just mapped. Say which steps AI should take off you and which have to stay with a person.
Read three suggestions that are not yours and vote for the one you would want built first. The queue is ranked by what people vote for.
Submit the link to the workflow you mapped.', 15, 1, null, '{}'::jsonb),
    ('quiz', 'Week 3 Quiz', null, 15, 3, null, '{"pass_mark":8,"question_count":10,"summative":true,"questions":[{"day":11,"question":"You want to show a colleague the screen you keep describing in meetings. What does Claude Design hand you that a written spec does not?","options":["A wireframe they can click through, share and comment on","A promise that what gets built will match what you asked for","A finished screen, signed off and ready for patients to use","A specification a developer can build from without changes","A record of the meetings where the screen was first discussed"],"correct":0,"explanation":"What comes back is the thing itself rather than a description of it: a prototype you can walk somebody through, share for comments, export or hand to Claude Code to build. A written spec leaves everybody picturing something slightly different, which is the problem it removes. It is still a quick draft, not a sign-off, and it does not replace the build."},{"day":11,"question":"Your first prototype comes back looking generic, as though it could be any company''s screen. What is most likely missing from the prompt?","options":["A longer description of the colours and fonts you would prefer","The name of a competitor whose screen you want it to resemble","A shorter prompt, since the detail is what made it generic","The document you already have, attached as what to build from","A request for something original rather than a template"],"correct":3,"explanation":"A prototype is only as specific as what you gave it. The spec, brief or page of notes you already have is what turns any company''s screen into yours. Styling instructions only polish something generic, copying a competitor borrows their thinking and cutting detail is the opposite of the fix."},{"day":12,"question":"The Word extension is open on a document your manager has already been through. How should you ask for the rewrite?","options":["As tracked changes, so each edit is accepted or rejected","As a clean copy, then compare the two documents by eye","In a chat, by pasting the document in and working there","As a list of edits for you to apply to the file yourself","As a rewritten file, keeping the original as a backup copy"],"correct":0,"explanation":"Tracked changes puts the edit in the real document and lets you accept it line by line. The comments are the other half of the job: ask Claude to summarise them and point out where they disagree, instead of reading twenty of them yourself. Every other option leaves you reconciling two documents by hand, which is the work the extension is there to remove."},{"day":12,"question":"You ask the PowerPoint extension to tighten three slides you have selected, on a deck that goes out this afternoon. Which choice matters most before you run it?","options":["Whether extended thinking is turned on for the request","Whether the deck is saved to OneDrive rather than locally","Whether it asks before each edit or applies them all","Whether the other Office extensions are installed as well","Whether the slides are on the current brand template"],"correct":2,"explanation":"The extension edits the real file, so the setting that changes what you end up with is whether you see each edit before it lands. Extended thinking changes how long Claude reasons, not what it is allowed to do, and where the file is saved changes nothing. Select the slides you want changed first. It is better at tidying up what is there than at building a deck from nothing."},{"day":13,"question":"You inherit a pricing workbook nobody documented and one assumption has to change. What does the Excel extension give you that a chat does not?","options":["A guarantee the model is right once it has finished with it","Answers about any cell, and the change made in the live file","A rebuild of the workbook from scratch, without the original","A search across the other workbooks saved on your drive","A record of every change made, kept for whoever audits it"],"correct":1,"explanation":"It works on the workbook that is open, so you can ask what a cell is doing, change an assumption and have the formulas updated in place, instead of pasting fragments into a chat and typing the answers back. It cannot reach a file you have not opened. It does not make the model right either. It writes into your file, so a wrong answer is a wrong number where it counts. Tell it how the sheet is built, then check what it changed."},{"day":13,"question":"You open the Excel extension on a workbook it has never seen and ask it to fix a formula that broke. What should you do before you ask?","options":["Tell it which cells are inputs and which are worked out by formulas","Turn the formulas off so it reads the values rather than the logic","Select only the single cell whose formula is broken, and nothing else","Rename the sheet after what it holds, so the context is in the title","Clear the cells it should not touch, and paste them back afterwards"],"correct":0,"explanation":"Left to guess how a sheet is built, it guesses: which cells you type into, which are worked out, what the currency is and whether a number is allowed to go negative. Say that first and the answer is about your model rather than a generic one. Turning the formulas off removes the logic it needs to read, and the other three are housekeeping that says nothing about how the workbook works. It writes into the live file, so check what it changed before you use the numbers."},{"day":14,"question":"The Outlook extension triages your inbox and hands you a reply with the recipients and subject already filled in. What is still yours?","options":["Deciding which folder each message should be filed into","Choosing which colleagues are allowed to see the thread","Reading the draft before it goes out under your name","Telling it which mail arrived while you were away","Setting the hours in which it may sort your inbox for you"],"correct":2,"explanation":"Triage sorts the inbox into what needs you, what it can draft and what is noise, and the drafts arrive ready to send. That is exactly why you read one before it goes. It is a public beta and it works on the message in front of it. An email sent in your name is yours, whoever wrote the first version."},{"day":15,"question":"You are choosing which of your workflows to map and put up for change. What makes one a strong candidate?","options":["It is the one your team complains about most in meetings","It runs on a rhythm and the same steps happen every time","It is the most complicated, so there is the most to gain from it","It is the one only you know how to do, so nobody will object","It is the one with the biggest single cost attached to it"],"correct":1,"explanation":"What AI takes off a workflow is repetition, so a job that runs on a rhythm with the same steps each time is the one with something to take. Complexity is not repetition, and the most complicated workflow is usually the one with the most judgement in it. A big one-off cost has nothing to automate. The loudest complaint tells you how the work feels rather than how tractable it is, and mapping the job only you understand makes the map harder for anybody to check."},{"day":5,"question":"Your team has a Project full of reference documents and a Connector to the system those documents describe. When does the Connector earn its keep?","options":["When you need what the system says now, not what it said then","Always, because a Connector is the more capable feature of the two","Only once the Project grows too large to search reliably","Never, since the two of them do the same job by other means","When the documents in the Project are more than a month old"],"correct":0,"explanation":"A Project holds background that changes slowly. A Connector fetches live state. Reference material belongs in the Project, and anything that moves belongs behind the Connector, whatever its age. A document goes stale when the system changes, not after a set number of weeks, and treating a stored document as current is a quiet source of wrong answers."},{"day":7,"question":"You have a recurring task, a one-off question, a method colleagues should reuse and a system Claude cannot reach. Which mapping is right?","options":["Skill, Scheduled Task, Project, Connector","Project, Skill, Connector, Artifact","Scheduled Task, Chat, Skill, Connector","Connector, Artifact, Scheduled Task, Skill","Scheduled Task, Chat, Project, Connector"],"correct":2,"explanation":"Recurring and predictable is a Scheduled Task, a one-off just needs a Chat, a method other people can run is a Skill and reaching a system is a Connector. The near miss puts a Project in the third slot. A Project holds background for your own chats, it does not package a method somebody else''s chat can trigger. Picking the wrong container is what makes simple work feel like hard work."}]}'::jsonb),
    ('submission_slot', 'Work sample (after)', null, 15, 4, null, '{"kind":"work_sample_post","visibility":"private"}'::jsonb),
    ('questionnaire_post', 'Your AI Score - see what three weeks did', null, 15, 5, null, '{}'::jsonb)
)
insert into public.programme_track_items
  (track_id, type, title, description, day_index, sort_order, learn_video_id, config_json)
select t.id, s.type, s.title, s.description, s.day_index, s.sort_order,
       (select v.id from public.learn_videos v where lower(v.title) = lower(s.learn_video_title) limit 1),
       s.config_json
  from spec s cross join track t
 where not exists (
   select 1 from public.programme_track_items i
    where i.track_id = t.id and i.day_index = s.day_index and i.sort_order = s.sort_order
 );

-- Sync titles and descriptions from the spec. These are seed-owned: admins
-- rename Learn videos, not track days, so overwriting is safe and it means
-- re-running the seed actually applies a wording change to an existing track.
update public.programme_track_items i
   set title = s.title, description = s.description
  from (values
    (0, 0, 'Your AI Score - 3-minute check-in', 'A quick self-assessment. It sets your starting point and unlocks the programme.'),
    (1, 0, 'What is AI and how does it work?', 'Prediction rather than lookup, the context window, training cutoff vs live data, the three failure sources and Time-Back Log setup.'),
    (1, 1, 'Task', 'Sign in to Claude with your Phlo email, install the desktop app, then run one real task from this week through it.
Submit the link to that task.'),
    (1, 4, 'Work sample (before)', null),
    (2, 0, 'When to use AI and when not to', null),
    (2, 1, 'Task', 'Pick three jobs from this week:
- one you are confident Claude will do well
- one you are confident Claude will not do well
- one where you are not sure
Before you open Claude, write down how you think each will go and rate yourself Certain, Fairly confident or Guessing. Then run all three, including the one you expect to fail.
Compare what you got with what you expected. Anything that worked when you thought it would not is a job to hand over from now on. Anything that came back wrong is one to keep checking.
Submit the link to one of these, ideally the one that surprised you most.'),
    (3, 0, 'Prompting', null),
    (3, 1, 'Task', 'Take a Project you''ve already built (or build a new one) and use the CRISPE framework in the instructions.
Run a chat here again and check the output.
Submit the Project as an example of one using a framework.'),
    (3, 2, 'Live session 1', null),
    (4, 0, 'Projects', null),
    (4, 1, 'Task', 'Pick one task you repeat and build a Project for it, giving it:
- custom instructions
- 2-3 knowledge files
- access with anyone else who could use it
Test it and check the output. If it is not what you need, the instructions are missing something, so add it and run it again.
Submit the link to the Project below.'),
    (5, 0, 'Connectors & MCP', null),
    (5, 1, 'Task', 'Go to Customize > Connectors and enable the tools you use daily.
Click on a specific connector and check the permissions that it allows by default. If you need additional functionality or are unsure what functionality is safe to enable for a specific connector, let Haseeb know.
Disconnect anything you added to have a look at and are not going to use.'),
    (5, 3, 'Week 1 Quiz', null),
    (6, 0, 'Skills', null),
    (6, 1, 'Task', 'Pick something you explain to Claude again and again: how a report should be laid out, how a summary should be structured, the checks a piece of work has to pass before you send it.
Go to Customize > Skills and build a Skill for it. Let the built-in skill-creator draft it from your description. Give it:
- a description saying when to use it
- one task only
- the method it should follow
Test it in a fresh chat: ask for the task without naming the Skill, and try a few different wordings.
If it does not fire, the description is too vague. Make it say plainly when the Skill should be used, then try again.
Submit the link to the chat where your Skill fired on its own.'),
    (7, 0, 'Scheduled Tasks', null),
    (7, 1, 'Task', 'Go to Scheduled in the sidebar and use New task to set up one job you do on a rhythm, with a frequency and a time you will be away from your desk.
Click Run now once and choose always allow on the permission prompts you recognise, or a scheduled run stalls waiting for you.
Do not tie it to a folder on your computer: those only run when you are there. Use your Connectors and files saved to your Claude account.
Submit the link to its first completed run, or a screenshot of it if there is no link to share.'),
    (8, 0, 'Artifacts', null),
    (8, 1, 'Task', 'Pick something you rebuild most weeks - a status update, a meeting-prep sheet, a checklist - and ask Claude to make it as an Artifact you can reuse.
Do not settle for the first draft. Ask for one change in plain English and watch it update. If Claude answers in the chat instead of opening a panel, check Settings > Capabilities for Code execution and file creation, and ask Haseeb if that setting is not yours to change.
Share it. On our Team plan anyone signed in with a Phlo account can open it, so use made-up numbers, keep logins and keys out of it, and ask Haseeb first if it needs to go outside Phlo.
Submit the link to your Artifact.'),
    (8, 2, 'Live session 2', null),
    (9, 0, 'Cowork', null),
    (9, 1, 'Task', 'Pick a boring job you keep putting off (e.g. merging a few documents into one summary, checking two lists against each other, tidying up and renaming a group of files). Put the files Cowork needs into one folder - don''t add anything else.
Open Cowork in the desktop app, point it to that folder and tell it the whole task in one sentence. Then set it to "Skip all approvals" to allow it to do the work without asking for approvals.
Cowork works on your real files, so keep this folder small and make sure there''s nothing unrelated or confidential in it.
Submit the link to the final output.'),
    (10, 0, 'Claude Design', null),
    (10, 1, 'Task', 'Describe one screen or document you wish already existed: a landing page, a settings screen, a pitch deck, a one-pager.
Open Claude Design at claude.ai/design, or from the sidebar in the desktop app. Build it there, then ask for one change in plain English instead of keeping the first version.
Export what you end up with. The Export button gives you PowerPoint, PDF or a standalone page.
It is a research preview, so treat what comes out as a draft. Keep confidential designs, patient-facing material and private code out of it.
Submit the link to the design, or to the file you exported.'),
    (10, 3, 'Week 2 Quiz', null),
    (11, 0, 'Claude Design 2', null),
    (11, 1, 'Task', 'Pick something you keep describing in words and hoping everyone pictures the same way: a screen you want built, a landing page, a one-pager.
Ask Claude Design to build it as something you can click through, not a picture of it. Attach the spec, brief or notes you already have, or you will get a screen that could belong to any company.
Ask for three versions, then take the best parts of each.
Export it as a PNG or a page, share it for comments, or hand it to Claude Code to build.
Submit the link to the prototype, or to what you exported.'),
    (12, 0, 'Word & PowerPoint extensions', null),
    (12, 1, 'Task', 'Install the Claude extensions for Word and PowerPoint from Microsoft AppSource. Office calls them add-ins, so look under Home > Add-ins on Windows or Tools > Add-ins on a Mac.
In each one''s settings, turn on ''Let Claude work across files'', and decide whether it should ask before each edit or just make them. On our Team plan that first setting is off until someone turns it on, so ask Haseeb if it is not yours to change.
In PowerPoint, open a deck you already have, select a few slides and ask for a specific change to those. It is better at tidying up what is there than at building a deck from nothing.
In Word, open a document with comments on it and ask Claude to summarise them and point out where they disagree. Turn track changes on first, so you can see every edit it makes.
Submit the link to the deck or the document you worked on.'),
    (13, 0, 'Excel extension', null),
    (13, 1, 'Task', 'Install the Claude extension for Excel from Microsoft AppSource, the same way as yesterday, and open a workbook you actually use.
Tell it how the sheet is built before you ask for anything: which cells are inputs, which are worked out by formulas, what the currency is, and whether a number can go negative. Left to guess, it guesses.
Then give it a real job. Clean up a messy import, fix a formula that broke, or reconcile two sheets that disagree and explain the gap.
Check what it did before you use the numbers. It can be wrong and sound certain, so reconcile the sections that matter and read the assumptions it made.
Submit the link to the workbook.'),
    (13, 2, 'Live session 3', null),
    (13, 4, 'Capstone', null),
    (14, 0, 'Outlook extension', null),
    (14, 1, 'Task', 'Install the Claude extension for Outlook. It is a public beta, and it opens from the ribbon when you have an email open.
Ask it to go through the inbox you dread on a Monday and sort it: what needs you, what it can draft for you, and what is noise.
Take one of its drafts, read it properly, then send it.
Submit a screenshot of what it sorted, since an Outlook email has no link you can share, or a link if something you made has one.'),
    (15, 0, 'Wrap-up and next steps', 'A look back over the fifteen days and the one thing that happens next: pick a workflow you own, map it and put it up to be changed.'),
    (15, 1, 'Task', 'Go to Workflows and use Add new workflow to map a job you own that runs every week and quietly eats your time. Give it the real numbers: how often it runs, the hours a week it takes, what it costs and every step from start to finish.
Go to Suggestions, use Suggest something and link it to the workflow you just mapped. Say which steps AI should take off you and which have to stay with a person.
Read three suggestions that are not yours and vote for the one you would want built first. The queue is ranked by what people vote for.
Submit the link to the workflow you mapped.'),
    (15, 3, 'Week 3 Quiz', null),
    (15, 4, 'Work sample (after)', null),
    (15, 5, 'Your AI Score - see what three weeks did', null)
  ) as s(day_index, sort_order, title, description)
 where i.day_index = s.day_index and i.sort_order = s.sort_order
   and i.track_id = (select id from public.programme_tracks where slug = 'core-programme')
   and (i.title is distinct from s.title or i.description is distinct from s.description);

-- Sync quiz config from the spec. Seed-owned: questions live in
-- lib/programme/quiz-content.ts and nothing in the app edits config_json,
-- so re-running the seed is how an edited question reaches an existing
-- track. Also repairs a pass_mark or question_count left over from an
-- earlier version of the spec.
update public.programme_track_items i
   set config_json = s.config_json
  from (values
    (5, 3, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":1,"question":"In an ordinary Chat, with web search turned off and no Connectors enabled, you ask Claude for the current list price of a product line. It answers with a precise figure, to the penny. Where did that number come from?","options":["It looked the price up and reported back what it found","It calculated it from related figures that it does hold","It predicted a plausible figure from patterns in its training data","It reported the last value it saw, so it is current unless the price moved","It inferred it from your earlier messages in this Chat"],"correct":2,"explanation":"Nothing was looked up. Claude predicts the next words, so a figure turns up in whatever shape the sentence needs, and the two decimal places are a writing habit, not evidence. When the number is right, that is the training data happening to agree with reality. Anything that changes over time needs a Connector, or a source you open yourself."},{"day":1,"question":"Two hours into a long Chat, Claude starts breaking a formatting rule you set at the very beginning and had been following all along. What is the likeliest cause?","options":["It has decided your later instructions override the earlier one","The Chat has outgrown what Claude can hold in view at once","Output quality degrades over a long session, so it needs restarting","Its training data disagrees with the rule that you set","The rule was not stated firmly enough for it to stick"],"correct":1,"explanation":"Everything Claude can see has to fit in one window, and a long chat pushes the start of it out of range. Say the rule again, or carry the essentials into a fresh chat. Saying it more firmly will not help. The instruction is not being ignored, it is no longer visible."},{"day":2,"question":"Which of these is the weakest candidate for handing to Claude?","options":["Drafting the first version of a recurring internal update","Summarising a supplier contract you will read properly afterwards","Signing off the final numbers in the month-end pack","Reformatting a messy stock export into a consistent structure","Drafting a tender rejection letter that is reviewed before it goes"],"correct":2,"explanation":"Drafting, summarising and reformatting are where Claude saves you time, and an awkward subject does not change that as long as you read the draft before it goes. Signing off is the one thing that cannot move, because you cannot hand over being accountable. Use Claude to prepare what the decision rests on, then make the decision yourself."},{"day":2,"question":"Two colleagues use Claude on similar work. One handed over a whole process end to end and is disappointed. The other handed over only the drafting and is not. What explains the gap?","options":["The second colleague simply writes better prompts than the first","Judgement and accountability do not transfer, but drafting does","The first colleague is working on genuinely more complex material","The second colleague has been using the tool for a lot longer","The first colleague needs a Project and the second already has one"],"correct":1,"explanation":"Complexity is not the dividing line, and neither is being good with the tool. What moves across is the blank page and the repetitive middle. What does not is deciding and owning the result, so handing over a whole process always disappoints at the point where somebody has to answer for it. Prompting and Projects both help, and neither changes that."},{"day":3,"question":"A prompt in a Chat returns content that is accurate and complete, but it reads like a different company wrote it. Which part of CRISPE is missing?","options":["Context","Instructions","Parameters","Role","Style"],"correct":4,"explanation":"Style is tone, register and voice. The content being right tells you Context and Instructions did their job. Role changes the expertise Claude writes from, not the voice it writes in, and Parameters set length, format and what to leave out. Correct but reads wrong means Style."},{"day":3,"question":"You have to write this month''s report in exactly the same shape as last month''s: the same sections, in the same order, with the same kind of summary at the top. Which part of CRISPE does most of the work?","options":["Instructions, listing out every formatting rule you can think of first","Example, pasting last month''s report so it can copy the shape","Parameters, specifying the length and the number of sections","Context, explaining who reads the report and what they need from it","Role, so it writes as the person who produced the original one"],"correct":1,"explanation":"One example says more than a page of rules, and it clears up the ambiguity a description always leaves behind. Parameters and Instructions can get the shape close and will never get the phrasing. Role and Context change how Claude thinks about the job, not what it hands you."},{"day":4,"question":"Every week you paste the same background into a new Chat before you can ask your real question: your team''s terminology, the format you need and the standing constraints. What fixes that properly?","options":["Keep the preamble in a note and paste it at the top of each Chat","Write one much longer prompt so that nothing important gets missed","Ask Claude to remember the background at the end of each Chat","Put the background and reference files in a Project","Add a Connector to the systems that background describes"],"correct":3,"explanation":"A Project holds the background, so every chat inside it starts briefed and nobody keeps a preamble up to date by hand. A pasted note goes out of date the moment the format changes, and a longer prompt just moves the repetition somewhere else. A Connector fetches live data, which is a different problem."},{"day":4,"question":"A Project you built answers the exact question you built it around very well, and anything slightly different badly. What does that tell you?","options":["The knowledge files you gave it are too small to generalise from","Projects are built for one job, so varied work belongs in a Chat","The instructions describe one task rather than how you work","You need a separate Project for each question you want to ask","Requests have to be phrased the way you phrased the original one"],"correct":2,"explanation":"A Project that only answers the question you built it around is a saved prompt with extra steps. The background is the method, the vocabulary and the constraints, and all of that carries across requests. Building one per question gives you more to maintain and the same problem again in a month."},{"day":5,"question":"Several times a day you copy the same figures out of the same system and paste them into a Chat. What is that a signal for?","options":["A Connector, so Claude can reach the system itself","A longer prompt that carries more of the background with it","A Project holding the most recent export of those figures","Nothing, copy and paste is perfectly fine at that volume","A Scheduled Task that pastes the figures in for you each morning"],"correct":0,"explanation":"Copying the same figures by hand several times a day is the clearest sign a Connector will pay for itself. A Project holds background that changes slowly, and an export dropped into one is out of date the moment you save it. A schedule automates the ferrying, so you get the same stale figures on a timer."},{"day":5,"question":"A colleague worries that connecting a system to Claude will expose data they are not allowed to see. Which of the following is correct?","options":["They are right, a Connector reads the system and bypasses its permissions","Connectors are limited to data that the system already publishes openly","It depends entirely on which Connector and which system it is","It is safe provided they enable only the permissions the job needs","A Connector works within the access they already have"],"correct":4,"explanation":"A Connector is a route, not a promotion. Your colleague sees what their own login already lets them see. Checking the permissions a Connector allows by default is still worth doing, and the day''s task asks for it, but that is not what keeps the answer safe. Worth being clear about in a regulated business, because the worry is common and it puts people off something useful."}]}'::jsonb),
    (10, 3, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":6,"question":"You have a reliable method for a recurring task and two colleagues want to use it. What makes a Skill the right home for it, rather than a Project or a saved prompt?","options":["They turn it on once, then it fires by itself","It stores the documents the task needs alongside the method","It runs to a timetable, whether or not the job came up","It gives Claude access to the system that the task depends on","It keeps the method private to the colleagues you name on it"],"correct":0,"explanation":"A Skill packages how you do something so other people''s chats can reach it. A colleague switches it on once, and after that the description is what makes it fire without anyone naming it. Documents belong in a Project, a timetable is a Scheduled Task, and system access is a Connector. Picking the wrong one is what makes simple work feel like hard work."},{"day":6,"question":"You built a Skill and it never fires unless you name it explicitly in the Chat. What is almost always wrong?","options":["The instructions inside the Skill have grown too long to parse","It has to be shared with your team before it will trigger at all","The task is too narrow for a Skill to be the right container","Its description is too vague to match what people actually ask","Skills only fire automatically for the person who created them"],"correct":3,"explanation":"The description is the trigger. Use this when formatting a monthly performance report fires when it should. Helps with reports never fires at all. Sharing changes who can reach a Skill, not whether it triggers, and a narrow task is exactly what a Skill wants."},{"day":7,"question":"From Scheduled in the sidebar you set a task to run the stock summary at 07:00 each Monday. You reach your desk at 08:30 and your laptop was shut overnight. What happens?","options":["It waits until you open the laptop, so the result arrives late","It ran at 07:00 without your machine, and the result is waiting","It is skipped entirely and runs again the following Monday","It fails, and you get a notification telling you that it failed","It ran at 07:00 but could not reach your Connectors while you were away"],"correct":1,"explanation":"Scheduled runs happen on Anthropic''s servers, so they keep to their timetable with your computer asleep and the desktop app shut, and your connected tools go with them. Nothing is deferred, skipped or failed. The one thing that still needs your machine is a task reaching files or apps on it. That is why you build a schedule on your Connectors and on files saved to your Claude account, and not on a folder."},{"day":7,"question":"A Scheduled Task you set up three weeks ago still runs, but you now rewrite most of its output before you use it. What should you do?","options":["Leave it running, since it is still saving you time overall","Delete it and go back to doing the whole task by hand again","Run it more often so that its output stays closer to current","Keep it, and log the saving as the full time the task once took","Fold what you keep rewriting back in, or retire the task"],"correct":4,"explanation":"Heavy editing means the task and the real work have drifted apart, and what you keep rewriting is the specification. Running it more often just gives you more to correct. Logging the old full cost is how a time saving turns into a number nobody believes. The saving is what the job costs now against what it cost before."},{"day":8,"question":"You have asked Claude for a checklist your team will use every week. Why ask for it as an Artifact rather than as text in the Chat?","options":["Artifacts are generated faster than the same answer in a Chat","Claude is more accurate when it writes into an Artifact","You get something you can edit, version and share on its own","It uses fewer messages, so you get more out of your limits","Anyone you share it with can edit your copy of it directly"],"correct":2,"explanation":"An Artifact is the output as an object instead of chat scrollback. You refine it in place, every version is kept, and you can share the checklist with people who do not need the conversation behind it. Speed and accuracy are the same either way. Sharing lets other people open and use it, which is not the same as giving them edit rights on yours."},{"day":8,"question":"You have built a margin calculator as an Artifact in Claude and you are about to share the link so your team can use it. This quarter''s real supplier prices are typed into it. What has to happen first?","options":["Share it, then message the team asking them not to forward the link","Nothing, a shared Artifact is reachable only by the people you send it to","Swap the real prices for made-up ones before you share it","Leave the real prices in and write a confidentiality note at the top of the page","Share it with only the two colleagues who actually need it"],"correct":2,"explanation":"Sharing is the step that changes who can see something. On our plan a shared Artifact opens for anyone at Phlo with the link, not just the people you had in mind, and it carries the files attached to the conversation that built it. Plenty of those people have no business seeing supplier pricing, so live figures are the wrong thing to leave in. A confidentiality note changes nothing about who can open the page, asking colleagues not to forward a link is not a control, and you cannot narrow a share to two names. It is everyone at Phlo or nobody."},{"day":9,"question":"Which of these is the strongest candidate for Cowork rather than an ordinary Chat?","options":["A question you need a single short answer to before this afternoon","Drafting an email to a supplier about a late delivery","Deciding which of two suppliers your team should move to","Working through a live document with a colleague at the same time","Merging six monthly reports into one summary and filing them"],"correct":4,"explanation":"Cowork earns its keep on assembly across a lot of files on your own machine. The work is tedious instead of difficult, and it ends in files instead of an answer. A short question and a draft are ordinary chat, deciding is yours, and two people cannot work in one Cowork session, so anything live and shared belongs elsewhere."},{"day":9,"question":"You are handing a job to Cowork in the desktop app and you have skipped the permission prompts so it can work without stopping to ask. What is keeping it away from files it has no business opening?","options":["The folder you pointed it at, and whatever you chose to put in it","Claude''s judgement about which of your files the task actually needs","The one-sentence brief, which tells it what it is allowed to open","The desktop app, which reaches your Claude account rather than your disk","Nothing much, so read every file it touched once the run has finished"],"correct":0,"explanation":"Skipping the prompts is what makes the folder the control. There is no per-step approval left, so the only thing between Cowork and a file is whether you put that file in scope before the run started. Claude has no way of knowing which of your documents are commercially sensitive. A brief describes the goal, it does not grant access. The desktop app is the route to your disk, not a limit on it: on our plan the run happens on Anthropic''s servers and reaches your files through that app, for the folders you connected and no others. Reading afterwards is worth doing, but by then it has already opened whatever was there."},{"day":10,"question":"You need a pitch deck for Monday and you want to shape the layout before it goes out. Where does Claude Design earn its place over an ordinary Chat?","options":["It writes the words on each slide more accurately than a Chat does","It signs the deck off, so nobody else has to review what it made","It keeps the deck''s source documents attached for the next revision","You shape the layout on a canvas and export the result as a PPTX","It is the only surface at Phlo that can read a PowerPoint file"],"correct":3,"explanation":"You get a canvas and a real export. You adjust spacing, colour and layout yourself, or ask for changes in plain English, and the Export button gives you PowerPoint, PDF or a standalone page. A Chat can draft the words, but hands them back as text for you to reassemble. Keeping the source documents for next time is what a Project is for. Nothing here removes the human review, and a Chat reads a PowerPoint file perfectly well."},{"day":10,"question":"Which of the following is the poorest fit for Claude Design as it stands today?","options":["An internal one-pager explaining a process change to your team","A rough settings screen, made to get a conversation started","A patient-facing leaflet going out under Phlo''s brand","A slide for Monday''s team meeting that you will talk over","A layout you want to react to before committing real time to it"],"correct":2,"explanation":"Two things make it the wrong fit. It is a research preview, so what comes out is a draft, and patient-facing material has to meet a standard a draft is not aiming at. Confidential designs and private code stay out for the same reason. Internal drafts, rough screens and something to react to are exactly what it is for."}]}'::jsonb),
    (15, 3, '{"pass_mark":8,"question_count":10,"summative":true,"questions":[{"day":11,"question":"You want to show a colleague the screen you keep describing in meetings. What does Claude Design hand you that a written spec does not?","options":["A wireframe they can click through, share and comment on","A promise that what gets built will match what you asked for","A finished screen, signed off and ready for patients to use","A specification a developer can build from without changes","A record of the meetings where the screen was first discussed"],"correct":0,"explanation":"What comes back is the thing itself rather than a description of it: a prototype you can walk somebody through, share for comments, export or hand to Claude Code to build. A written spec leaves everybody picturing something slightly different, which is the problem it removes. It is still a quick draft, not a sign-off, and it does not replace the build."},{"day":11,"question":"Your first prototype comes back looking generic, as though it could be any company''s screen. What is most likely missing from the prompt?","options":["A longer description of the colours and fonts you would prefer","The name of a competitor whose screen you want it to resemble","A shorter prompt, since the detail is what made it generic","The document you already have, attached as what to build from","A request for something original rather than a template"],"correct":3,"explanation":"A prototype is only as specific as what you gave it. The spec, brief or page of notes you already have is what turns any company''s screen into yours. Styling instructions only polish something generic, copying a competitor borrows their thinking and cutting detail is the opposite of the fix."},{"day":12,"question":"The Word extension is open on a document your manager has already been through. How should you ask for the rewrite?","options":["As tracked changes, so each edit is accepted or rejected","As a clean copy, then compare the two documents by eye","In a chat, by pasting the document in and working there","As a list of edits for you to apply to the file yourself","As a rewritten file, keeping the original as a backup copy"],"correct":0,"explanation":"Tracked changes puts the edit in the real document and lets you accept it line by line. The comments are the other half of the job: ask Claude to summarise them and point out where they disagree, instead of reading twenty of them yourself. Every other option leaves you reconciling two documents by hand, which is the work the extension is there to remove."},{"day":12,"question":"You ask the PowerPoint extension to tighten three slides you have selected, on a deck that goes out this afternoon. Which choice matters most before you run it?","options":["Whether extended thinking is turned on for the request","Whether the deck is saved to OneDrive rather than locally","Whether it asks before each edit or applies them all","Whether the other Office extensions are installed as well","Whether the slides are on the current brand template"],"correct":2,"explanation":"The extension edits the real file, so the setting that changes what you end up with is whether you see each edit before it lands. Extended thinking changes how long Claude reasons, not what it is allowed to do, and where the file is saved changes nothing. Select the slides you want changed first. It is better at tidying up what is there than at building a deck from nothing."},{"day":13,"question":"You inherit a pricing workbook nobody documented and one assumption has to change. What does the Excel extension give you that a chat does not?","options":["A guarantee the model is right once it has finished with it","Answers about any cell, and the change made in the live file","A rebuild of the workbook from scratch, without the original","A search across the other workbooks saved on your drive","A record of every change made, kept for whoever audits it"],"correct":1,"explanation":"It works on the workbook that is open, so you can ask what a cell is doing, change an assumption and have the formulas updated in place, instead of pasting fragments into a chat and typing the answers back. It cannot reach a file you have not opened. It does not make the model right either. It writes into your file, so a wrong answer is a wrong number where it counts. Tell it how the sheet is built, then check what it changed."},{"day":13,"question":"You open the Excel extension on a workbook it has never seen and ask it to fix a formula that broke. What should you do before you ask?","options":["Tell it which cells are inputs and which are worked out by formulas","Turn the formulas off so it reads the values rather than the logic","Select only the single cell whose formula is broken, and nothing else","Rename the sheet after what it holds, so the context is in the title","Clear the cells it should not touch, and paste them back afterwards"],"correct":0,"explanation":"Left to guess how a sheet is built, it guesses: which cells you type into, which are worked out, what the currency is and whether a number is allowed to go negative. Say that first and the answer is about your model rather than a generic one. Turning the formulas off removes the logic it needs to read, and the other three are housekeeping that says nothing about how the workbook works. It writes into the live file, so check what it changed before you use the numbers."},{"day":14,"question":"The Outlook extension triages your inbox and hands you a reply with the recipients and subject already filled in. What is still yours?","options":["Deciding which folder each message should be filed into","Choosing which colleagues are allowed to see the thread","Reading the draft before it goes out under your name","Telling it which mail arrived while you were away","Setting the hours in which it may sort your inbox for you"],"correct":2,"explanation":"Triage sorts the inbox into what needs you, what it can draft and what is noise, and the drafts arrive ready to send. That is exactly why you read one before it goes. It is a public beta and it works on the message in front of it. An email sent in your name is yours, whoever wrote the first version."},{"day":15,"question":"You are choosing which of your workflows to map and put up for change. What makes one a strong candidate?","options":["It is the one your team complains about most in meetings","It runs on a rhythm and the same steps happen every time","It is the most complicated, so there is the most to gain from it","It is the one only you know how to do, so nobody will object","It is the one with the biggest single cost attached to it"],"correct":1,"explanation":"What AI takes off a workflow is repetition, so a job that runs on a rhythm with the same steps each time is the one with something to take. Complexity is not repetition, and the most complicated workflow is usually the one with the most judgement in it. A big one-off cost has nothing to automate. The loudest complaint tells you how the work feels rather than how tractable it is, and mapping the job only you understand makes the map harder for anybody to check."},{"day":5,"question":"Your team has a Project full of reference documents and a Connector to the system those documents describe. When does the Connector earn its keep?","options":["When you need what the system says now, not what it said then","Always, because a Connector is the more capable feature of the two","Only once the Project grows too large to search reliably","Never, since the two of them do the same job by other means","When the documents in the Project are more than a month old"],"correct":0,"explanation":"A Project holds background that changes slowly. A Connector fetches live state. Reference material belongs in the Project, and anything that moves belongs behind the Connector, whatever its age. A document goes stale when the system changes, not after a set number of weeks, and treating a stored document as current is a quiet source of wrong answers."},{"day":7,"question":"You have a recurring task, a one-off question, a method colleagues should reuse and a system Claude cannot reach. Which mapping is right?","options":["Skill, Scheduled Task, Project, Connector","Project, Skill, Connector, Artifact","Scheduled Task, Chat, Skill, Connector","Connector, Artifact, Scheduled Task, Skill","Scheduled Task, Chat, Project, Connector"],"correct":2,"explanation":"Recurring and predictable is a Scheduled Task, a one-off just needs a Chat, a method other people can run is a Skill and reaching a system is a Connector. The near miss puts a Project in the third slot. A Project holds background for your own chats, it does not package a method somebody else''s chat can trigger. Picking the wrong container is what makes simple work feel like hard work."}]}'::jsonb)
  ) as s(day_index, sort_order, config_json)
 where i.day_index = s.day_index and i.sort_order = s.sort_order
   and i.type = 'quiz'
   and i.track_id = (select id from public.programme_tracks where slug = 'core-programme')
   and i.config_json is distinct from s.config_json;

-- Re-bind any day whose Learn video has since been added. Only fills nulls,
-- so an admin's manual binding is never overwritten.
--
-- VIDEO ITEMS ONLY. A use_example is the "now go do it" half of the day and
-- stays unbound: if it shared the video, one tick on /learn would complete
-- both items and G1 would be reachable without doing any exercise.
update public.programme_track_items i
   set learn_video_id = v.id
  from public.learn_videos v
 where i.learn_video_id is null
   and i.type = 'video'
   and lower(v.title) = lower(i.title)
   and i.track_id = (select id from public.programme_tracks where slug = 'core-programme');
